import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The evidence store — verdicts are a pure function, so cache them","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/evidence-store.md","filePath":"vendored/graphopt/project/retros/evidence-store.md"}`),a={name:`graphopt/project/retros/evidence-store.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="the-evidence-store-—-verdicts-are-a-pure-function-so-cache-them" tabindex="-1">The evidence store — verdicts are a pure function, so cache them <a class="header-anchor" href="#the-evidence-store-—-verdicts-are-a-pure-function-so-cache-them" aria-label="Permalink to “The evidence store — verdicts are a pure function, so cache them”">​</a></h1><p><code>python -m catopt_discovery.pipeline</code> recomputed every verdict on every run (~2 min on this box; the retro&#39;s &quot;~25 s&quot; was a quieter machine) and scattered the results across <code>/tmp</code> JSON dumps and prose retros — so &quot;what did we measure, and did it change?&quot; was answered by grepping prose. A verdict is <strong>deterministic given the corpus, the search rule set and the verification code</strong> — a perfect cache. <code>python -m catopt_discovery.evidence</code> is that store: a <code>sqlite3</code> database (stdlib only, no new dependencies) wired into the pipeline as a pure side effect.</p><p>Reproduce:</p><pre><code>.venv/bin/python python -m catopt_discovery.pipeline --evidence-db /tmp/laws.db
.venv/bin/python python -m catopt_discovery.pipeline --evidence-db /tmp/laws.db \\
    --use-evidence-cache
.venv/bin/python python -m catopt_discovery.evidence --report /tmp/laws.db
.venv/bin/python python -m catopt_discovery.evidence --report /tmp/laws.db --ships
</code></pre><h2 id="_1-schema" tabindex="-1">1. Schema <a class="header-anchor" href="#_1-schema" aria-label="Permalink to “1. Schema”">​</a></h2><div class="language-sql"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">candidates(alpha_key </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">TEXT</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> PRIMARY KEY</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">, </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">name</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">, family, proposal_json)</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">verdicts(alpha_key, corpus_hash, rules_hash, code_rev, run_id,</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">         holdout, numeric_true, derivable, witness_json, relation,</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">         census_sites, relaxed, matches, example, fires,</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">         fire_cases_json, changed, paid, verify_fail, drop_pct,</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">         cert</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">, enode_ratio, verdict, ts,</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">         PRIMARY KEY</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> (alpha_key, corpus_hash, rules_hash,</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">                      code_rev, run_id))</span></span></code></pre></div><p><code>alpha_key</code> is <code>repr(law_proposal._key(lhs, rhs))</code> — the alpha-normal equality the pipeline already de-duplicates by. The verdict columns are exactly the fields the <code>Evidence</code> record computes; the store measures nothing, it persists. <code>drop_pct</code> is percent, <code>numeric_true</code> is NULL/0/1, <code>verdict</code> is <code>&quot;SHIP&quot;</code> or <code>&quot;no:&lt;reason&gt;&quot;</code>.</p><h2 id="_2-the-scope-keys-—-when-a-cached-verdict-is-valid" tabindex="-1">2. The scope keys — when a cached verdict is valid <a class="header-anchor" href="#_2-the-scope-keys-—-when-a-cached-verdict-is-valid" aria-label="Permalink to “2. The scope keys — when a cached verdict is valid”">​</a></h2><p>A hit requires <strong>all three</strong> scope keys to match:</p><table tabindex="0"><thead><tr><th>key</th><th>hashed over</th><th>invalidates on</th></tr></thead><tbody><tr><td><code>corpus_hash</code></td><td><code>source:name:shape_key(term)</code> per bench+model case</td><td>corpus change (new model, new shape)</td></tr><tr><td><code>rules_hash</code></td><td><code>repr(_key)</code> of every search rule</td><td><code>--holdout</code>, or any library edit</td></tr><tr><td><code>code_rev</code></td><td><code>git rev-parse --short HEAD</code>, <code>+&lt;diffhash&gt;</code> of <code>packages</code>/<code>tools</code>/<code>bench</code> when dirty</td><td>any verification-code edit, committed or not</td></tr></tbody></table><p>A <code>&quot;unknown&quot;</code> rev (git cannot answer) is written but never served. Two fields are not round-tripped: <code>match_term</code> (not serializable — the admission emitter binds from <code>fire_cases</code>&#39; live model terms) and <code>reach</code>&#39;s per-model rows (only their aggregates are read downstream).</p><h2 id="_3-measured" tabindex="-1">3. Measured <a class="header-anchor" href="#_3-measured" aria-label="Permalink to “3. Measured”">​</a></h2><p>Same corpus, same code, second run:</p><pre><code>evidence db: /tmp/laws.db (rev 76623dd+4089e750,
    corpus cffaf641ea55, rules 85f1cd92ec69)
    — 50/50 verdicts served from cache
</code></pre><p><strong>50/50 hits; 128 s → 6.6 s</strong> (the residual is building the corpus and running census/propose — required to know the keys). A JSON diff of a cache-read run vs a fresh-measure run: all 50 rows equal except <code>closure_ratio</code> on 3 rows (2.35 vs 2.47, 1.64 vs 1.61, 35.43 vs 35.40) — see §5; verdicts, ranking and every other field identical.</p><h2 id="_4-the-query-that-pays-for-the-store" tabindex="-1">4. The query that pays for the store <a class="header-anchor" href="#_4-the-query-that-pays-for-the-store" aria-label="Permalink to “4. The query that pays for the store”">​</a></h2><pre><code>$ law_evidence.py --report /tmp/laws.db --flips
  census:mul_select [census-naturality]
    05:24 run=bc39e932 corpus=cffaf641 rules=e505362d: SHIP
    05:20 run=c81a405c corpus=cffaf641 rules=85f1cd92: no:not new (duplicate)
</code></pre><p>One row of history tells the whole held-out story: <code>census:mul_select</code> is a duplicate under the full library (<code>rules=85f1…</code>) and SHIP the moment <code>select_mul</code> is held out (<code>rules=e505…</code>) — the verdict flip is the <em>context</em> flip, visible in the same table. <code>--ships</code> answers &quot;every candidate ever marked SHIP&quot;; <code>--history &lt;substr&gt;</code> dumps every recorded verdict for a candidate.</p><h2 id="_5-honesty-—-what-a-hit-means-and-what-it-does-not" tabindex="-1">5. Honesty — what a hit means and what it does not <a class="header-anchor" href="#_5-honesty-—-what-a-hit-means-and-what-it-does-not" aria-label="Permalink to “5. Honesty — what a hit means and what it does not”">​</a></h2><ul><li><strong>Scope, not prophecy.</strong> A verdict is <code>(corpus, rules, code)</code>- scoped. A corpus edit, a library edit, or a <code>tensor.py</code> change under a dirty tree all correctly invalidate — the holdout run above took <code>rules_hash</code> and <code>code_rev</code> misses (0/50) exactly as designed. Never read a cached verdict as &quot;still true&quot; — read it as &quot;true for that context&quot;.</li><li><strong><code>enode_ratio</code> is noisy at the source.</strong> Two <em>fresh</em> runs on an identical corpus produce different enode counts (set-iteration order differs per process — <code>PYTHONHASHSEED</code>). The cache faithfully replays the recorded value; it does not manufacture the noise. Verdicts are stable because the ship gate reads the ratio against a 2.0× bound, far from the noise floor — a candidate near the bound could flip across fresh runs and the store honestly records both.</li><li><strong>The db must live outside <code>tools/</code></strong> (or any hashed path): an untracked file under <code>tools/</code> is hashed into <code>code_rev</code>, so a store there would invalidate itself on every write.</li><li>Re-measurement is never hidden: <code>--evidence-db</code> without <code>--use-evidence-cache</code> always measures fresh and appends; the <code>run_id</code> count in the report is literally &quot;how many runs saw this verdict&quot;.</li></ul><h2 id="gates" tabindex="-1">Gates <a class="header-anchor" href="#gates" aria-label="Permalink to “Gates”">​</a></h2><p><code>ruff check</code> / <code>ruff format --check</code> clean on <code>python -m catopt_discovery.evidence</code> and <code>python -m catopt_discovery.pipeline</code>; pipeline runs to completion fresh, cached, and under <code>--holdout select_mul</code> (rediscovery still PASS — <code>census:mul_select</code> SHIP at rank 1 of 50). No test suite run — tooling-only change.</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};